def is_expired(issued_at_seconds, ttl_seconds, now_ms):
    if issued_at_seconds < 0 or ttl_seconds < 0 or now_ms < 0:
        raise ValueError('timestamps must be non-negative')
    return now_ms >= issued_at_seconds + ttl_seconds

def attempt(operation, max_attempts):
    if max_attempts < 1:
        raise ValueError('max_attempts must be positive')
    last_error = None
    for _ in range(max_attempts + 1):
        try:
            return operation()
        except RuntimeError as exc:
            last_error = exc
    raise last_error

